data: {"id":"chatcmpl-20261012130717353565277c955d5689VVZ3Vmx","created":1791810437,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_58d187e8af6a416db1acca3a","index":0,"type":"function","function":{"name":"Write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"\\nconcurrent_reservation.py\\n\\nSimulates two concurrent transactions that both try to reserve 6 units of\\nitem_id 1 in inventory.db.\\n\\nEach thread:\\n  1. Opens its own SQLite connection with isolation_level=None (autocommit\\n     off at the driver level), so transaction boundaries are controlled\\n     explicitly with BEGIN / COMMIT statements.\\n  2. Issues BEGIN (deferred). In WAL mode, the first read establishes a\\n     consistent snapshot of the database (snapshot isolation).\\n  3. Reads quantity and reserved for item_id 1.\\n  4. Waits at a threading.Barrier so BOTH transactions are open and holding\\n     their snapshots at the same time -- guaranteeing the transactions\\n     overlap in time.\\n  5. If (quantity - reserved) >= 6 in its snapshot, updates the reserved\\n     column and COMMITs.\\n\\nBecause both transactions read the same snapshot, only one can commit its\\nwrite: SQLite detects the write-write conflict against the stale snapshot\\n(SQLITE_BUSY_SNAPSHOT, surfaced as \\\"database is locked\\\") and the second\\ntransaction must roll back. This first-committer-wins behavior is what\\nprevents a lost update / over-reservation.\\n\\nNote: running this twice in a row will show both transactions declining to\\nreserve, because after the first run only 4 units remain available\\n(10 - 6). Reset the row to demo the conflict again.\\n\\\"\\\"\\\"\\n\\nimport sqlite3\\nimport threading\\nimport time\\n\\nDB_PATH = \\\"inventory.db\\\"\\nITEM_ID = 1\\nRESERVE_QTY = 6\\nNUM_TXNS = 2\\n\\n# Barrier ensuring both transactions have read their snapshot before either\\n# one attempts to write -- this forces the transactions to overlap in time.\\nsnapshot_barrier = threading.Barrier(NUM_TXNS, timeout=10)\\n\\n\\ndef run_transaction(name: str) -> None:\\n    # isolation_level=None -> driver autocommit; we control BEGIN/COMMIT\\n    # explicitly. Separate connection per thread (SQLite connections are\\n    # not safe to share across threads).\\n    conn = sqlite3.connect(DB_PATH, isolation_level=None, timeout=10.0)\\n    try:\\n        conn.execute(\\\"BEGIN\\\")  # deferred; snapshot taken at the first read\\n        quantity, reserved = conn.execute(\\n            \\\"SELECT quantity, reserved FROM inventory WHERE item_id = ?\\\",\\n            (ITEM_ID,),\\n        ).fetchone()\\n        available = quantity - reserved\\n        print(f\\\"[{name}] BEGIN ok; snapshot: quantity={quantity} \\\"\\n              f\\\"reserved={reserved} available={available}\\\")\\n\\n        # Both transactions are now open on the same snapshot.\\n        snapshot_barrier.wait()\\n\\n        if available >= RESERVE_QTY:\\n            # Small delay to widen the overlap window before writing.\\n            time.sleep(0.2)\\n            try:\\n                conn.execute(\\n                    \\\"UPDATE inventory SET reserved = reserved + ? \\\"\\n                    \\\"WHERE item_id = ?\\\",\\n                    (RESERVE_QTY, ITEM_ID),\\n                )\\n                conn.execute(\\\"COMMIT\\\")\\n                print(f\\\"[{name}] reserved {RESERVE_QTY} units; COMMIT ok\\\")\\n            except sqlite3.OperationalError as exc:\\n                # Write-write conflict: another transaction already committed\\n                # on top of our snapshot. Snapshot isolation rejected the\\n                # write; roll back cleanly instead of over-reserving.\\n                try:\\n                    conn.execute(\\\"ROLLBACK\\\")\\n                except sqlite3.OperationalError:\\n                    pass\\n                print(f\\\"[{name}] COMMIT failed (stale snapshot / write \\\"\\n                      f\\\"conflict): {exc}\\\")\\n        else:\\n            print(f\\\"[{name}] only {available} available; nothing to reserve\\\")\\n            conn.execute(\\\"ROLLBACK\\\")\\n    finally:\\n        conn.close()\\n\\n\\ndef main() -> None:\\n    # WAL mode is what enables snapshot isolation with concurrent readers\\n    # and a single writer. Must be set outside any transaction.\\n    setup = sqlite3.connect(DB_PATH, isolation_level=None)\\n    mode = setup.execute(\\\"PRAGMA journal_mode=WAL;\\\").fetchone()[0]\\n    setup.close()\\n    print(f\\\"journal mode: {mode}\\\")\\n\\n    threads = [\\n        threading.Thread(target=run_transaction, args=(f\\\"txn-{i + 1}\\\",))\\n        for i in range(NUM_TXNS)\\n    ]\\n    for t in threads:\\n        t.start()\\n    for t in threads:\\n        t.join()\\n\\n    # Show the resulting state after both transactions finish.\\n    conn = sqlite3.connect(DB_PATH)\\n    quantity, reserved = conn.execute(\\n        \\\"SELECT quantity, reserved FROM inventory WHERE item_id = ?\\\",\\n        (ITEM_ID,),\\n    ).fetchone()\\n    conn.close()\\n    print(f\\\"final state: item_id={ITEM_ID} quantity={quantity} \\\"\\n          f\\\"reserved={reserved}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"file_path\":\"/home/agent/workspace/concurrent_reservation.py\"}"}}]}}]}

