data: {"id":"chatcmpl-2026101213130942551882c955d568BRxRnBuz","created":1791810789,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_20e7bfc4328a41a1a5c7e325","index":0,"type":"function","function":{"name":"Write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"\\nconcurrent_reservation.py\\n\\nSimulates two concurrent transactions that both try to reserve 6 units of\\nitem_id 1 in inventory.db, records a timestamped history of every read and\\nwrite operation, and afterward analyzes that history for serialization\\nanomalies (lost update, write skew) using a dependency-graph check.\\n\\nTransaction model (per thread):\\n  1. Own SQLite connection with isolation_level=None; transaction bounds are\\n     explicit BEGIN / COMMIT statements.\\n  2. BEGIN (deferred); in WAL mode the first read pins a snapshot.\\n  3. Reads quantity/reserved for item_id 1 (recorded).\\n  4. threading.Barrier => both transactions hold snapshots simultaneously\\n     (guaranteed overlap in time).\\n  5. If available (quantity - reserved) >= 6 in the snapshot: UPDATE reserved\\n     and COMMIT. First-committer-wins decides which write survives.\\n\\nSnapshot isolation rejects the second writer's COMMIT (SQLITE_BUSY_SNAPSHOT,\\nsurfaced as \\\"database is locked\\\") because its snapshot was invalidated by the\\nfirst writer. That abort is precisely what breaks the would-be lost-update\\ncycle in the serialization graph.\\n\\nAfter both threads finish, the script prints:\\n  * the interleaved concurrent history,\\n  * a serializability analysis: per-transaction outcomes, the dependency\\n    graph over committed transactions (wr / rw / ww edges), a cycle check\\n    (Kahn's algorithm), anomaly verdicts, the equivalent serial order, and\\n    an explanation of which cycle snapshot isolation prevented.\\n\\nNote: running twice in a row shows both transactions declining to reserve\\n(only 4 units remain). Reset the row to demo the conflict again.\\n\\\"\\\"\\\"\\n\\nimport sqlite3\\nimport threading\\nimport time\\n\\nDB_PATH = \\\"inventory.db\\\"\\nITEM_ID = 1\\nRESERVE_QTY = 6\\nNUM_TXNS = 2\\nITEM_KEY = f\\\"inventory[item_id={ITEM_ID}]\\\"\\n\\n# --- operation history ------------------------------------------------------\\n# Entries: (elapsed_s, txn_name, op, detail, item, values)\\nhistory: list = []\\nhistory_lock = threading.Lock()\\n_t0 = time.perf_counter()\\n\\n\\ndef record(name: str, op: str, detail: str = \\\"\\\", item=None, values=None) -> None:\\n    \\\"\\\"\\\"Append a timestamped operation to the shared history.\\\"\\\"\\\"\\n    with history_lock:\\n        history.append((time.perf_counter() - _t0, name, op, detail, item, values))\\n\\n\\n# Barrier ensuring both transactions have read their snapshot before either\\n# one attempts to write -- this forces the transactions to overlap in time.\\nsnapshot_barrier = threading.Barrier(NUM_TXNS, timeout=10)\\n\\n\\ndef run_transaction(name: str) -> None:\\n    # isolation_level=None -> driver autocommit; we control BEGIN/COMMIT\\n    # explicitly. Separate connection per thread (SQLite connections are\\n    # not safe to share across threads).\\n    conn = sqlite3.connect(DB_PATH, isolation_level=None, timeout=10.0)\\n    try:\\n        conn.execute(\\\"BEGIN\\\")  # deferred; snapshot taken at the first read\\n        record(name, \\\"BEGIN\\\", \\\"deferred transaction started\\\")\\n\\n        quantity, reserved = conn.execute(\\n            \\\"SELECT quantity, reserved FROM inventory WHERE item_id = ?\\\",\\n            (ITEM_ID,),\\n        ).fetchone()\\n        available = quantity - reserved\\n        record(name, \\\"READ\\\",\\n               f\\\"quantity={quantity} reserved={reserved} available={available}\\\",\\n               item=ITEM_KEY,\\n               values={\\\"quantity\\\": quantity, \\\"reserved\\\": reserved})\\n\\n        # Both transactions are now open on the same snapshot.\\n        snapshot_barrier.wait()\\n        record(name, \\\"BARRIER\\\",\\n               \\\"both transactions open and holding their snapshot\\\")\\n\\n        if available >= RESERVE_QTY:\\n            # Small delay to widen the overlap window before writing.\\n            time.sleep(0.2)\\n            intended = reserved + RESERVE_QTY\\n            try:\\n                conn.execute(\\n                    \\\"UPDATE inventory SET reserved = reserved + ? \\\"\\n                    \\\"WHERE item_id = ?\\\",\\n                    (RESERVE_QTY, ITEM_ID),\\n                )\\n                record(name, \\\"WRITE\\\",\\n                       f\\\"UPDATE reserved {reserved} -> {intended} \\\"\\n                       f\\\"(based on snapshot available={available})\\\",\\n                       item=ITEM_KEY,\\n                       values={\\\"before\\\": reserved, \\\"after\\\": intended})\\n                conn.execute(\\\"COMMIT\\\")\\n                record(name, \\\"COMMIT\\\", f\\\"committed reserved={intended}\\\")\\n            except sqlite3.OperationalError as exc:\\n                # Write-write conflict: another transaction already committed\\n                # on top of our snapshot. Snapshot isolation rejected the\\n                # write; roll back cleanly instead of over-reserving.\\n                try:\\n                    conn.execute(\\\"ROLLBACK\\\")\\n                except sqlite3.OperationalError:\\n                    pass\\n                record(name, \\\"ABORT\\\",\\n                       f\\\"COMMIT rejected (stale snapshot): {exc}; \\\"\\n                       f\\\"rolled back, no units reserved\\\",\\n                       item=ITEM_KEY,\\n                       values={\\\"attempted_before\\\": reserved,\\n                               \\\"attempted_after\\\": intended})\\n        else:\\n            record(name, \\\"SKIP\\\",\\n                   f\\\"only {available} available (< {RESERVE_QTY}); \\\"\\n                   f\\\"nothing to reserve\\\")\\n            conn.execute(\\\"ROLLBACK\\\")\\n            record(name, \\\"ROLLBACK\\\", \\\"read-only transaction ended\\\")\\n    finally:\\n        conn.close()\\n\\n\\ndef print_history() -> None:\\n    \\\"\\\"\\\"Print the interleaved concurrent history in a clear format.\\\"\\\"\\\"\\n    print(\\\"\\\\n=== CONCURRENT HISTORY ===\\\")\\n    print(f\\\"{'time (s)':>10}  {'transaction':<12} {'op':<10} detail\\\")\\n    print(\\\"-\\\" * 78)\\n    for elapsed, name, op, detail, _item, _vals in sorted(history,\\n                                                          key=lambda e: e[0]):\\n        print(f\\\"{elapsed:>10.6f}  {name:<12} {op:<10} {detail}\\\")\\n    print(\\\"-\\\" * 78)\\n\\n\\ndef analyze_serializability() -> None:\\n    \\\"\\\"\\\"Analyze the recorded history: build the dependency graph over\\n    committed transactions, check for cycles and anomalies, print verdict.\\\"\\\"\\\"\\n    print(\\\"\\\\n=== SERIALIZABILITY ANALYSIS ===\\\")\\n\\n    # ---- collect per-transaction operations (exclude system entries) ----\\n    txn_ops: dict = {}\\n    for _elapsed, name, op, _detail, item, values in history:\\n        if name == \\\"system\\\":\\n            continue\\n        txn_ops.setdefault(name, []).append((_elapsed, op, item, values))\\n\\n    outcomes = {}\\n    for name, ops in txn_ops.items():\\n        if any(op == \\\"COMMIT\\\" for _, op, _, _ in ops):\\n            outcomes[name] = \\\"COMMITTED\\\"\\n        elif any(op == \\\"ABORT\\\" for _, op, _, _ in ops):\\n            outcomes[name] = \\\"ABORTED (write rejected, no committed effects)\\\"\\n        else:\\n            outcomes[name] = \\\"ROLLED BACK (read-only, no committed effects)\\\"\\n\\n    committed = sorted(n for n, s in outcomes.items() if s == \\\"COMMITTED\\\")\\n    others = sorted(n for n in outcomes if n not in committed)\\n\\n    print(\\\"\\\\nTransaction outcomes:\\\")\\n    for name in sorted(txn_ops):\\n        print(f\\\"  {name}: {outcomes[name]}\\\")\\n    if others:\\n        print(f\\\"  -> aborted/rolled-back transactions are logically erased; \\\"\\n              f\\\"the dependency graph is built over the committed set \\\"\\n              f\\\"{committed} only.\\\")\\n\\n    def reads_of(n):\\n        # (time, reserved value read)\\n        return [(t, (v or {}).get(\\\"reserved\\\"))\\n                for t, op, it, v in txn_ops[n]\\n                if op == \\\"READ\\\" and it == ITEM_KEY]\\n\\n    def writes_of(n):\\n        # (time, reserved before, reserved after)\\n        return [(t, (v or {}).get(\\\"before\\\"), (v or {}).get(\\\"after\\\"))\\n                for t, op, it, v in txn_ops[n]\\n                if op == \\\"WRITE\\\" and it == ITEM_KEY]\\n\\n    # ---- dependency graph over COMMITTED transactions ----\\n    # Edge types on the shared item (edge points from \\\"must come first\\\" to\\n    # \\\"must come after\\\" in any equivalent serial order):\\n    #   wr (reads-from) : writer -> reader   (reader read the writer's value)\\n    #   rw (anti-dep)   : reader -> writer   (reader read the value the\\n    #                                         writer overwrote)\\n    #   ww              : writer -> writer   (first write precedes second)\\n    edges: dict = {n: set() for n in committed}\\n    reasons: list = []\\n\\n    def add_edge(a, b, reason):\\n        if a != b and b not in edges[a]:\\n            edges[a].add(b)\\n            reasons.append(f\\\"  {a} -> {b}   {reason}\\\")\\n\\n    for i, a in enumerate(committed):\\n        for b in committed[i + 1:]:\\n            for ta, r_a in reads_of(a):\\n                for tb, before_b, after_b in writes_of(b):\\n                    if tb < ta and r_a == after_b:\\n                        add_edge(b, a, f\\\"wr({ITEM_KEY}): {a} read \\\"\\n                                       f\\\"reserved={r_a} written by {b}\\\")\\n                    if tb > ta and r_a == before_b:\\n                        add_edge(a, b, f\\\"rw({ITEM_KEY}): {a} read \\\"\\n                                       f\\\"reserved={r_a}; {b} overwrote it\\\")\\n            for tb, r_b in reads_of(b):\\n                for ta, before_a, after_a in writes_of(a):\\n                    if ta < tb and r_b == after_a:\\n                        add_edge(a, b, f\\\"wr({ITEM_KEY}): {b} read \\\"\\n                                       f\\\"reserved={r_b} written by {a}\\\")\\n                    if ta > tb and r_b == before_a:\\n                        add_edge(b, a, f\\\"rw({ITEM_KEY}): {b} read \\\"\\n                                       f\\\"reserved={r_b}; {a} overwrote it\\\")\\n            for ta, _ba, _aa in writes_of(a):\\n                for tb, _bb, _ab in writes_of(b):\\n                    if ta < tb:\\n                        add_edge(a, b, f\\\"ww({ITEM_KEY}): {a} wrote before {b}\\\")\\n                    elif tb < ta:\\n                        add_edge(b, a, f\\\"ww({ITEM_KEY}): {b} wrote before {a}\\\")\\n\\n    print(\\\"\\\\nDependency graph (serialization graph, committed txns):\\\")\\n    print(f\\\"  nodes: {', '.join(committed) if committed else '(none)'}\\\")\\n    if reasons:\\n        print(\\\"\\\\n\\\".join(reasons))\\n    else:\\n        print(\\\"  edges: (none)\\\")\\n\\n    # ---- cycle check (Kahn's algorithm) ----\\n    indeg = {n: 0 for n in committed}\\n    for a in committed:\\n        for b in edges[a]:\\n            indeg[b] += 1\\n    ready = sorted(n for n in committed if indeg[n] == 0)\\n    topo = []\\n    while ready:\\n        n = ready.pop()\\n        topo.append(n)\\n        for m in edges[n]:\\n            indeg[m] -= 1\\n            if indeg[m] == 0:\\n                ready.append(m)\\n    acyclic = len(topo) == len(committed)\\n\\n    # ---- anomaly checks (over committed transactions) ----\\n    print(\\\"\\\\nAnomaly checks:\\\")\\n    lost_update = False\\n    for i, a in enumerate(committed):\\n        for b in committed[i + 1:]:\\n            a_w, b_w = writes_of(a), writes_of(b)\\n            a_r, b_r = reads_of(a), reads_of(b)\\n            if a_w and b_w:\\n                ta_w = min(t for t, _, _ in a_w)\\n                tb_w = min(t for t, _, _ in b_w)\\n                if (any(t < tb_w for t, _ in a_r)\\n                        and any(t < ta_w for t, _ in b_r)):\\n                    lost_update = True\\n                    print(f\\\"  lost update : YES — {a} and {b} both committed \\\"\\n                          f\\\"writes to {ITEM_KEY} derived from overlapping \\\"\\n                          f\\\"reads\\\")\\n    if not lost_update:\\n        print(f\\\"  lost update : NO — both transactions wrote {ITEM_KEY} from \\\"\\n              f\\\"the same snapshot, so the writes conflict; only one \\\"\\n              f\\\"committed (first-committer-wins aborted the loser). No \\\"\\n              f\\\"committed update was overwritten.\\\")\\n    print(f\\\"  write skew  : NO — both transactions' write sets are the same \\\"\\n          f\\\"row ({ITEM_KEY}), not disjoint, and they could not both commit; \\\"\\n          f\\\"write skew requires two committed transactions with disjoint \\\"\\n          f\\\"writes validated against overlapping reads.\\\")\\n\\n    # ---- verdict ----\\n    print()\\n    if not committed:\\n        print(\\\"VERDICT: no committed transactions — schedule is trivially \\\"\\n              \\\"conflict-serializable.\\\")\\n        return\\n    if acyclic:\\n        serial = \\\" -> \\\".join(topo)\\n        print(\\\"VERDICT: dependency graph is ACYCLIC -> the schedule IS \\\"\\n              \\\"conflict-serializable.\\\")\\n        print(f\\\"Equivalent serial order of committed transactions: {serial}\\\")\\n        for name in others:\\n            print(f\\\"  ({name} was aborted/rolled back; its reads observed the \\\"\\n                  f\\\"pre-write snapshot, consistent with serializing it before \\\"\\n                  f\\\"{topo[0]}. The committed projection alone is equivalent \\\"\\n                  f\\\"to the serial history [{serial}].)\\\")\\n    else:\\n        print(\\\"VERDICT: dependency graph contains a CYCLE -> the schedule is \\\"\\n              \\\"NOT conflict-serializable.\\\")\\n\\n    # ---- explain the cycle snapshot isolation prevented ----\\n    if acyclic and len(committed) == 1:\\n        winner = committed[0]\\n        for loser in others:\\n            if any(op == \\\"ABORT\\\" and it == ITEM_KEY\\n                   for _, op, it, _ in txn_ops[loser]):\\n                print(\\\"\\\\nWhat snapshot isolation prevented:\\\")\\n                print(f\\\"  {winner} and {loser} both read {ITEM_KEY} at \\\"\\n                      f\\\"reserved=0 and both attempted to write it.\\\")\\n                print(f\\\"  Had both writes committed, the graph would gain rw \\\"\\n                      f\\\"anti-dependency edges in both directions \\\"\\n                      f\\\"({loser} -> {winner} and {winner} -> {loser}: each \\\"\\n                      f\\\"read before the other wrote) plus a ww edge — a \\\"\\n                      f\\\"cycle, i.e. the classic LOST UPDATE.\\\")\\n                print(f\\\"  First-committer-wins rejected {loser}'s COMMIT \\\"\\n                      f\\\"(stale snapshot), so the cycle never formed and the \\\"\\n                      f\\\"committed schedule remains serializable.\\\")\\n\\n\\ndef main() -> None:\\n    # WAL mode is what enables snapshot isolation with concurrent readers\\n    # and a single writer. Must be set outside any transaction.\\n    setup = sqlite3.connect(DB_PATH, isolation_level=None)\\n    mode = setup.execute(\\\"PRAGMA journal_mode=WAL;\\\").fetchone()[0]\\n    setup.close()\\n    print(f\\\"journal mode: {mode}\\\")\\n\\n    threads = [\\n        threading.Thread(target=run_transaction, args=(f\\\"txn-{i + 1}\\\",))\\n        for i in range(NUM_TXNS)\\n    ]\\n    for t in threads:\\n        t.start()\\n    for t in threads:\\n        t.join()\\n\\n    # Final committed state, read from a fresh connection after both\\n    # transactions have completed, is recorded as part of the history.\\n    conn = sqlite3.connect(DB_PATH)\\n    quantity, reserved = conn.execute(\\n        \\\"SELECT quantity, reserved FROM inventory WHERE item_id = ?\\\",\\n        (ITEM_ID,),\\n    ).fetchone()\\n    conn.close()\\n    record(\\\"system\\\", \\\"FINAL-STATE\\\",\\n           f\\\"item_id={ITEM_ID} quantity={quantity} reserved={reserved}\\\")\\n\\n    print_history()\\n    analyze_serializability()\\n\\n    print(\\\"\\\\n=== FINAL COMMITTED STATE ===\\\")\\n    print(f\\\"item_id={ITEM_ID} quantity={quantity} reserved={reserved}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"file_path\":\"/home/agent/workspace/concurrent_reservation.py\"}"}}]}}]}

